package com.dongqh.luckyhub.fulfillment;
import com.dongqh.luckyhub.fulfillment.dto.CreateFulfillmentTaskCommand;import com.dongqh.luckyhub.fulfillment.enums.*;import com.dongqh.luckyhub.fulfillment.model.*;import com.dongqh.luckyhub.fulfillment.service.*;import com.dongqh.luckyhub.integration.gateway.GatewayResult;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import java.time.Duration;import static org.assertj.core.api.Assertions.*;
@SpringBootTest class FulfillmentSafetyTests {@Autowired FulfillmentTaskService tasks;@Autowired FulfillmentStateService state;@Autowired JdbcTemplate jdbc;@AfterEach void clean(){jdbc.update("DELETE FROM fulfillment_attempt");jdbc.update("DELETE FROM fulfillment_quarantine");jdbc.update("DELETE FROM fulfillment_task");}
 @Test void rejectsFullReceiverPhoneAndRegion(){assertThatThrownBy(()->new LogisticsFulfillmentPayload("SKU",1,"张三","13812345678","浙江省杭州市西湖区" )).isInstanceOf(IllegalArgumentException.class);}
 @Test void boundsErrorsAndPersistsOnlyMaskedLogisticsSnapshot(){tasks.create(new CreateFulfillmentTaskCommand("SAFE-1","TEST","1",FulfillmentType.LOGISTICS,1L,new LogisticsFulfillmentPayload("SKU",1,"张*","138****5678","浙江省杭州市***"),5));var claim=state.claimDue(1,Duration.ofSeconds(30)).get(0);state.recordResult(claim,GatewayResult.retryable("E","x".repeat(800)),1);String rows=jdbc.queryForObject("SELECT CONCAT(request_payload,'|',COALESCE(last_error_message,'')) FROM fulfillment_task WHERE fulfillment_no='SAFE-1'",String.class);assertThat(rows).doesNotContain("张三","13812345678","西湖区","secret","token");assertThat(rows.length()).isLessThan(900);assertThat(jdbc.queryForObject("SELECT CHAR_LENGTH(error_message) FROM fulfillment_attempt WHERE fulfillment_no='SAFE-1'",Integer.class)).isLessThanOrEqualTo(500);}
 @Test void manualRetryResolvesQuarantineAndTerminateStopsPendingTask(){tasks.create(new CreateFulfillmentTaskCommand("OPS-R","TEST","1",FulfillmentType.POINTS,1L,new PointsFulfillmentPayload(1,"x"),5));jdbc.update("UPDATE fulfillment_task SET status='QUARANTINED' WHERE fulfillment_no='OPS-R'");Long id=jdbc.queryForObject("SELECT id FROM fulfillment_task WHERE fulfillment_no='OPS-R'",Long.class);jdbc.update("INSERT INTO fulfillment_quarantine(task_id,fulfillment_no,reason,quarantined_at) VALUES(?,?,?,NOW(3))",id,"OPS-R","test");assertThat(tasks.retryQuarantined("OPS-R",99L,"确认可重试").status()).isEqualTo(FulfillmentStatus.PENDING);assertThat(jdbc.queryForObject("SELECT resolution FROM fulfillment_quarantine WHERE task_id=?",String.class,id)).isEqualTo("RETRY");tasks.create(new CreateFulfillmentTaskCommand("OPS-T","TEST","2",FulfillmentType.POINTS,1L,new PointsFulfillmentPayload(1,"x"),5));assertThat(tasks.terminate("OPS-T",99L,"停止").status()).isEqualTo(FulfillmentStatus.TERMINATED);}
}
